import {
  IconPerson,
  IconRelative,
  IconShare,
  IconTrash,
} from '../../../../../assets/images';
import {SizeDP} from '../../../../../constants/Size';
import {Status} from '../../../../../model/enum/common.enum';
import {LIST_APP_TYPE} from '../../../home/component/CreateTicket/helper';

export const getListAction = (
  status: Status,
  isCheck: any,
  actionFrom?: LIST_APP_TYPE,
) => {
  if (actionFrom === 'eBLDT') {
    return [
      {
        id: 1,
        key: 'TK.review',
        value: 'review',
        icon: <IconPerson width={SizeDP(18)} height={SizeDP(18)} />,
      },
    ];
  }
  switch (status) {
    case Status.processing:
      return isCheck
        ? [
            {
              id: 1,
              key: 'TK.review',
              value: 'review',
              icon: <IconPerson width={SizeDP(18)} height={SizeDP(18)} />,
            },
            {
              id: 2,
              key: 'TK.cancel',
              value: 'cancel',
              icon: <IconTrash width={SizeDP(18)} height={SizeDP(18)} />,
            },
            {
              id: 3,
              key: 'TK.forwarded',
              value: 'forwarded',
              icon: <IconShare width={SizeDP(18)} height={SizeDP(18)} />,
            },
          ]
        : [
            {
              id: 1,
              key: 'TK.review',
              value: 'review',
              icon: <IconPerson width={SizeDP(18)} height={SizeDP(18)} />,
            },
            {
              id: 3,
              key: 'TK.forwarded',
              value: 'forwarded',
              icon: <IconShare width={SizeDP(18)} height={SizeDP(18)} />,
            },
          ];
    default:
      return [];
  }
};
